import React, { useState, useEffect } from "react";
import Confetti from "react-confetti";
import "./App.css";

// Dynamic Category List based on your actual images
const CATEGORIES = ["All", "Wedding", "Birthday", "Portrait", "Nature"];

// EXACT IMAGE MAPPING FROM YOUR PUBLIC/IMAGES FOLDER
const GALLERY_IMAGES = [
  // Birthday Images
  { id: 1, title: "Birthday Celebration 1", category: "Birthday", filename: "b1.jpg", desc: "Joyful birthday party moments." },
  { id: 2, title: "Birthday Celebration 2", category: "Birthday", filename: "b2.jpg", desc: "Delicious cake smash & decor." },
  { id: 3, title: "Birthday Celebration 3", category: "Birthday", filename: "b3.jpg", desc: "Fun party gathering." },
  { id: 4, title: "Birthday Celebration 4", category: "Birthday", filename: "b4.jpg", desc: "Special birthday highlights." },
  { id: 5, title: "Birthday Celebration 5", category: "Birthday", filename: "b5.jpg", desc: "Vibrant birthday smiles." },

  // Wedding Images
  { id: 6, title: "Royal Wedding 1", category: "Wedding", filename: "w1.jpg", desc: "Grand bridal ceremony." },
  { id: 7, title: "Royal Wedding 2", category: "Wedding", filename: "w2.jpg", desc: "Beautiful couple shoot." },
  { id: 8, title: "Royal Wedding 3", category: "Wedding", filename: "w3.jpg", desc: "Traditional wedding decor." },
  { id: 9, title: "Royal Wedding 4", category: "Wedding", filename: "w4.jpg", desc: "Aesthetic reception moments." },
  { id: 10, title: "Royal Wedding 5", category: "Wedding", filename: "w5.jpg", desc: "Unforgettable wedding night." },

  // Portrait Images
  { id: 11, title: "Studio Portrait 1", category: "Portrait", filename: "p1.jpg", desc: "Professional portrait shoot." },
  { id: 12, title: "Studio Portrait 2", category: "Portrait", filename: "p2.jpg", desc: "Monochrome artistic portrait." },
  { id: 13, title: "Studio Portrait 3", category: "Portrait", filename: "p3.jpg", desc: "Dramatic lighting portrait." },

  // Nature Images (n1 - n16)
  { id: 14, title: "Nature View 1", category: "Nature", filename: "n1.jpg", desc: "Scenic outdoor view." },
  { id: 15, title: "Nature View 4", category: "Nature", filename: "n4.jpg", desc: "Vibrant floral shot." },
  { id: 16, title: "Nature View 5", category: "Nature", filename: "n5.jpg", desc: "Lush nature scenery." },
  { id: 17, title: "Nature View 6", category: "Nature", filename: "n6.jpg", desc: "Coastal mountain shore." },
  { id: 18, title: "Nature View 7", category: "Nature", filename: "n7.jpg", desc: "Serene natural landscape." },
  { id: 19, title: "Nature View 8", category: "Nature", filename: "n8.jpg", desc: "Green valley view." },
  { id: 20, title: "Nature View 9", category: "Nature", filename: "n9.jpg", desc: "Golden hour outdoors." },
  { id: 21, title: "Nature View 10", category: "Nature", filename: "n10.jpg", desc: "Forest path." },
  { id: 22, title: "Nature View 13", category: "Nature", filename: "n13.jpg", desc: "Quiet riverbank." },
  { id: 23, title: "Nature View 14", category: "Nature", filename: "n14.jpg", desc: "Mountain sky." },
  { id: 24, title: "Nature View 15", category: "Nature", filename: "n15.jpg", desc: "Red flower bloom." },
  { id: 25, title: "Nature View 16", category: "Nature", filename: "n16.jpg", desc: "Wild nature texture." }
];

const SERVICES = [
  { title: "Wedding Photography", category: "Wedding", desc: "Capturing your special day with elegance & timeless beauty.", icon: "💍" },
  { title: "Birthday & Parties", category: "Birthday", desc: "Fun & lively event coverage for all joyful milestones.", icon: "🎂" },
  { title: "Portrait Shoots", category: "Portrait", desc: "Studio & outdoor personal profile photos.", icon: "📸" },
  { title: "Nature & Outdoors", category: "Nature", desc: "Breathtaking landscape and environmental photography.", icon: "🌿" }
];

const PACKAGES = [
  { id: "basic", name: "Basic Event", price: 25000, features: ["2 Hours Coverage", "25 Edited Photos", "HD Online Gallery", "Soft Copies in USB"] },
  { id: "standard", name: "Standard Shoot", price: 55000, features: ["5 Hours Coverage", "60 Edited Photos", "1 Printed Album Frame", "Full Digital Access"] },
  { id: "premium", name: "Royal Premium", price: 120000, features: ["Full Day Coverage", "150+ Edited Photos", "Luxury Storybook Album", "Drone Shots Included"] },
  { id: "custom", name: "Customized Package", price: 35000, features: ["Tailored Services", "Flexible Timings", "Custom Deliverables"] }
];

// File Path Helper
const getImagePath = (filename) => process.env.PUBLIC_URL + `/images/${filename}`;

export default function App() {
  const [activeTab, setActiveTab] = useState("home");
  const [darkMode, setDarkMode] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("All");
  const [activeLightbox, setActiveLightbox] = useState(null);

  const [favorites, setFavorites] = useState(() => {
    const saved = localStorage.getItem("fav_photos");
    return saved ? JSON.parse(saved) : [];
  });

  const [currentSlide, setCurrentSlide] = useState(0);

  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [loginForm, setLoginForm] = useState({ username: "", password: "" });
  const [runConfetti, setRunConfetti] = useState(false);

  const [selectedPackage, setSelectedPackage] = useState(PACKAGES[0]);
  const [extraHours, setExtraHours] = useState(0);
  const [droneAddon, setDroneAddon] = useState(false);
  const [albumAddon, setAlbumAddon] = useState(false);
  const [bookingDetails, setBookingDetails] = useState({ name: "", email: "", date: "", time: "", category: "Wedding" });
  const [bookingPopup, setBookingPopup] = useState(false);

  const [contactMsg, setContactMsg] = useState({ name: "", email: "", message: "" });
  const [contactSubmitted, setContactSubmitted] = useState(false);

  useEffect(() => {
    localStorage.getItem("fav_photos");
    localStorage.setItem("fav_photos", JSON.stringify(favorites));
  }, [favorites]);

  useEffect(() => {
    if (darkMode) {
      document.body.classList.add("dark-mode");
    } else {
      document.body.classList.remove("dark-mode");
    }
  }, [darkMode]);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % GALLERY_IMAGES.length);
    }, 3500);
    return () => clearInterval(timer);
  }, []);

  const toggleFavorite = (id) => {
    setFavorites((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const handleLoginSubmit = (e) => {
    e.preventDefault();
    if (loginForm.username && loginForm.password) {
      setIsLoggedIn(true);
      setShowLoginModal(false);
      setRunConfetti(true);
      setTimeout(() => setRunConfetti(false), 4500);
    }
  };

  const calculateTotalPrice = () => {
    let total = selectedPackage.price + extraHours * 5000;
    if (droneAddon) total += 15000;
    if (albumAddon) total += 10000;
    return total;
  };

  const handlePackageSelectAndBook = (pkg) => {
    setSelectedPackage(pkg);
    setActiveTab("booking");
  };

  const handleServiceClick = (cat) => {
    setSelectedCategory(cat);
    setActiveTab("gallery");
  };

  const handleBookingSubmit = (e) => {
    e.preventDefault();
    setBookingPopup(true);
  };

  const handleContactSubmit = (e) => {
    e.preventDefault();
    setContactSubmitted(true);
    setTimeout(() => setContactSubmitted(false), 4000);
  };

  const filteredGallery = GALLERY_IMAGES.filter((img) => {
    const matchesCat = selectedCategory === "All" || img.category === selectedCategory;
    const matchesSearch = img.title.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCat && matchesSearch;
  });

  const displayedImages = activeTab === "favorites"
    ? GALLERY_IMAGES.filter((img) => favorites.includes(img.id))
    : filteredGallery;

  return (
    <div className="app-container">
      {runConfetti && <Confetti width={window.innerWidth} height={window.innerHeight} recycle={false} numberOfPieces={350} />}

      <nav className="navbar">
        <div className="nav-brand" onClick={() => setActiveTab("home")}>📷 SHUTTER STORIES</div>
        <div className="nav-right-controls">
          <button className="theme-btn" onClick={() => setDarkMode(!darkMode)}>
            {darkMode ? "☀️ Light" : "🌙 Dark"}
          </button>
          <button className="hamburger" onClick={() => setMenuOpen(!menuOpen)}>☰</button>
        </div>
        <ul className={`nav-links ${menuOpen ? "open" : ""}`}>
          {["home", "gallery", "services", "packages", "about", "favorites", "booking", "contact"].map((tab) => (
            <li key={tab}>
              <button
                className={activeTab === tab ? "active" : ""}
                onClick={() => { setActiveTab(tab); setMenuOpen(false); }}
              >
                {tab.charAt(0).toUpperCase() + tab.slice(1)} {tab === "favorites" ? `(${favorites.length})` : ""}
              </button>
            </li>
          ))}
          <li>
            {isLoggedIn ? (
              <button className="auth-btn logout-btn" onClick={() => setIsLoggedIn(false)}>Logout</button>
            ) : (
              <button className="auth-btn login-btn" onClick={() => setShowLoginModal(true)}>Login</button>
            )}
          </li>
        </ul>
      </nav>

      {activeTab === "home" && (
        <>
          <section className="hero-section">
            <div className="hero-backdrop">
              <img src={getImagePath("hero-bg.jpg")} alt="Hero Background" />
              <div className="hero-overlay"></div>
            </div>
            <div className="hero-content">
              <h1>Capturing Timeless Stories</h1>
              <p>Professional photography in Pakistan for Weddings, Birthdays, Portraits & Nature.</p>
              <button className="btn-primary" onClick={() => setActiveTab("booking")}>Book Your Session Now</button>
            </div>
          </section>

          <section>
            <h2 className="section-title">Featured Highlights</h2>
            <div className="slider-wrapper">
              <div className="slider-track" style={{ transform: `translateX(-${currentSlide * 100}%)` }}>
                {GALLERY_IMAGES.map((img) => (
                  <div className="slide-item" key={img.id}>
                    <img src={getImagePath(img.filename)} alt={img.title} />
                    <div className="slider-caption">{img.title} — <span>{img.category}</span></div>
                  </div>
                ))}
              </div>
              <button className="slider-btn left" onClick={() => setCurrentSlide((prev) => (prev === 0 ? GALLERY_IMAGES.length - 1 : prev - 1))}>❮</button>
              <button className="slider-btn right" onClick={() => setCurrentSlide((prev) => (prev + 1) % GALLERY_IMAGES.length)}>❯</button>
            </div>
          </section>
        </>
      )}

      {(activeTab === "gallery" || activeTab === "favorites") && (
        <section>
          <h2 className="section-title">{activeTab === "favorites" ? "Your Liked Photos" : "Portfolio Gallery"}</h2>

          {activeTab !== "favorites" && (
            <div className="controls-bar">
              <input type="text" placeholder="Search photos by title..." className="search-input" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              <div className="filter-bar">
                {CATEGORIES.map((cat) => (
                  <button key={cat} className={`filter-btn ${selectedCategory === cat ? "active" : ""}`} onClick={() => setSelectedCategory(cat)}>
                    {cat}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="gallery-grid">
            {displayedImages.length > 0 ? (
              displayedImages.map((img) => (
                <div className="gallery-card" key={img.id}>
                  <div className="img-wrapper">
                    <img src={getImagePath(img.filename)} alt={img.title} onClick={() => setActiveLightbox(img)} />
                  </div>
                  <div className="card-info">
                    <span>{img.title}</span>
                    <button className="fav-btn" onClick={() => toggleFavorite(img.id)}>
                      {favorites.includes(img.id) ? "❤️" : "🤍"}
                    </button>
                  </div>
                </div>
              ))
            ) : (
              <p style={{ textAlign: "center", gridColumn: "1/-1" }}>No pictures found in this section.</p>
            )}
          </div>
        </section>
      )}

      {activeTab === "services" && (
        <section>
          <h2 className="section-title">Our Photography Services</h2>
          <p style={{ textAlign: "center", marginBottom: "2rem" }}>Click on any service to view its photo category!</p>
          <div className="services-grid">
            {SERVICES.map((srv, idx) => (
              <div className="service-card" key={idx} onClick={() => handleServiceClick(srv.category)}>
                <div className="service-icon">{srv.icon}</div>
                <h3>{srv.title}</h3>
                <p>{srv.desc}</p>
                <span style={{ color: "var(--primary-color)", fontWeight: "bold" }}>View Category Photos →</span>
              </div>
            ))}
          </div>
        </section>
      )}

      {activeTab === "packages" && (
        <section>
          <h2 className="section-title">Packages & Pricing (PKR)</h2>
          <div className="packages-grid">
            {PACKAGES.map((pkg) => (
              <div key={pkg.id} className={`package-card ${selectedPackage.id === pkg.id ? "selected" : ""}`} onClick={() => handlePackageSelectAndBook(pkg)}>
                <h3>{pkg.name}</h3>
                <p className="price">Rs. {pkg.price.toLocaleString()}</p>
                <ul>
                  {pkg.features.map((feat, idx) => <li key={idx}>✓ {feat}</li>)}
                </ul>
                <button className="btn-primary">Select & Book Directly</button>
              </div>
            ))}
          </div>

          <div className="calc-box">
            <h3>⚡ Custom Price Estimator</h3>
            <p>Selected Base Package: <strong>{selectedPackage.name} (Rs. {selectedPackage.price.toLocaleString()})</strong></p>
            <div className="calc-options">
              <label>Extra Hours (Rs. 5,000/hr): 
                <input type="number" min="0" value={extraHours} onChange={(e) => setExtraHours(Number(e.target.value))} style={{ marginLeft: "10px", width: "60px" }} />
              </label>
              <label><input type="checkbox" checked={droneAddon} onChange={(e) => setDroneAddon(e.target.checked)} /> Drone Aerial Coverage (+Rs. 15,000)</label>
              <label><input type="checkbox" checked={albumAddon} onChange={(e) => setAlbumAddon(e.target.checked)} /> Printed Luxury Album (+Rs. 10,000)</label>
            </div>
            <h4>Total Calculated Cost: <span style={{ color: "var(--primary-color)", fontSize: "1.4rem" }}>Rs. {calculateTotalPrice().toLocaleString()}</span></h4>
            <button className="btn-primary" onClick={() => setActiveTab("booking")}>Proceed to Direct Booking</button>
          </div>
        </section>
      )}

      {activeTab === "about" && (
        <section>
          <h2 className="section-title">About Shutter Stories</h2>
          <div className="about-card">
            <div className="about-img-box">
              <img src={getImagePath("p1.jpg")} alt="About Studio" />
            </div>
            <div className="about-text">
              <h3>We Craft Memories Into Fine Art</h3>
              <p>
                Shutter Stories is a premier photography agency in Pakistan dedicated to creating aesthetic visual stories. From royal weddings to personal portraits and outdoor shoots, we bring high-end equipment and creative passion to every event.
              </p>
              <div className="about-stats">
                <div className="stat-item">
                  <h4>500+</h4>
                  <p>Shoots Done</p>
                </div>
                <div className="stat-item">
                  <h4>100%</h4>
                  <p>Happy Clients</p>
                </div>
                <div className="stat-item">
                  <h4>8+ Yrs</h4>
                  <p>Experience</p>
                </div>
              </div>
            </div>
          </div>
        </section>
      )}

      {activeTab === "booking" && (
        <section>
          <h2 className="section-title">Book Your Session</h2>
          <div className="form-container">
            <form onSubmit={handleBookingSubmit}>
              <div className="form-group">
                <label>Full Name</label>
                <input type="text" required value={bookingDetails.name} onChange={(e) => setBookingDetails({ ...bookingDetails, name: e.target.value })} />
              </div>
              <div className="form-group">
                <label>Email Address</label>
                <input type="email" required value={bookingDetails.email} onChange={(e) => setBookingDetails({ ...bookingDetails, email: e.target.value })} />
              </div>
              <div className="form-group">
                <label>Event Category</label>
                <select value={bookingDetails.category} onChange={(e) => setBookingDetails({ ...bookingDetails, category: e.target.value })}>
                  {CATEGORIES.filter(c => c !== "All").map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="form-group">
                <label>Selected Package</label>
                <input type="text" disabled value={`${selectedPackage.name} - Rs. ${calculateTotalPrice().toLocaleString()}`} />
              </div>
              <div className="form-group">
                <label>Preferred Date</label>
                <input type="date" required value={bookingDetails.date} onChange={(e) => setBookingDetails({ ...bookingDetails, date: e.target.value })} />
              </div>
              <div className="form-group">
                <label>Preferred Time</label>
                <input type="time" required value={bookingDetails.time} onChange={(e) => setBookingDetails({ ...bookingDetails, time: e.target.value })} />
              </div>
              <button type="submit" className="btn-primary" style={{ width: "100%", marginTop: "1rem" }}>Confirm Booking Request</button>
            </form>
          </div>
        </section>
      )}

      {activeTab === "contact" && (
        <section>
          <h2 className="section-title">Contact Us</h2>
          <div className="form-container">
            {contactSubmitted && <p style={{ color: "green", fontWeight: "bold" }}>Message sent successfully! We will get back to you shortly.</p>}
            <form onSubmit={handleContactSubmit}>
              <div className="form-group">
                <label>Name</label>
                <input type="text" required value={contactMsg.name} onChange={(e) => setContactMsg({ ...contactMsg, name: e.target.value })} />
              </div>
              <div className="form-group">
                <label>Email</label>
                <input type="email" required value={contactMsg.email} onChange={(e) => setContactMsg({ ...contactMsg, email: e.target.value })} />
              </div>
              <div className="form-group">
                <label>Message</label>
                <textarea rows="4" required value={contactMsg.message} onChange={(e) => setContactMsg({ ...contactMsg, message: e.target.value })}></textarea>
              </div>
              <button type="submit" className="btn-primary" style={{ width: "100%" }}>Send Message</button>
            </form>
          </div>
        </section>
      )}

      {showLoginModal && (
        <div className="modal-overlay" onClick={() => setShowLoginModal(false)}>
          <div className="compact-modal" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={() => setShowLoginModal(false)}>✕</button>
            <h3>Sign In</h3>
            <form onSubmit={handleLoginSubmit}>
              <div className="form-group">
                <input type="text" placeholder="Username" required value={loginForm.username} onChange={(e) => setLoginForm({ ...loginForm, username: e.target.value })} />
              </div>
              <div className="form-group">
                <input type="password" placeholder="Password" required value={loginForm.password} onChange={(e) => setLoginForm({ ...loginForm, password: e.target.value })} />
              </div>
              <button type="submit" className="btn-primary" style={{ width: "100%" }}>Login</button>
            </form>
          </div>
        </div>
      )}

      {activeLightbox && (
        <div className="modal-overlay" onClick={() => setActiveLightbox(null)}>
          <div style={{ position: "relative", textAlign: "center", maxWidth: "90%" }}>
            <button className="close-btn" style={{ color: "white" }} onClick={() => setActiveLightbox(null)}>✕</button>
            <img src={getImagePath(activeLightbox.filename)} alt={activeLightbox.title} style={{ maxHeight: "80vh", borderRadius: "10px", maxWidth: "100%" }} />
            <h3 style={{ color: "white", marginTop: "1rem" }}>{activeLightbox.title} ({activeLightbox.category})</h3>
            <p style={{ color: "#e0f2f1" }}>{activeLightbox.desc}</p>
          </div>
        </div>
      )}

      {bookingPopup && (
        <div className="modal-overlay" onClick={() => setBookingPopup(false)}>
          <div className="compact-modal" style={{ maxWidth: "420px" }}>
            <button className="close-btn" onClick={() => setBookingPopup(false)}>✕</button>
            <h3>🎉 Booking Confirmed!</h3>
            <p>Thank you, <strong>{bookingDetails.name}</strong>!</p>
            <p>Your <strong>{bookingDetails.category}</strong> session is scheduled for <strong>{bookingDetails.date}</strong> at <strong>{bookingDetails.time}</strong>.</p>
            <p>Total Price: <strong>Rs. {calculateTotalPrice().toLocaleString()}</strong></p>
            <button className="btn-primary" onClick={() => setBookingPopup(false)} style={{ width: "100%" }}>Close</button>
          </div>
        </div>
      )}

      <button className="scroll-to-top" onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}>↑</button>

      <footer className="footer">
        <div className="footer-socials">
          <a href="https://wa.me/923001234567" target="_blank" rel="noopener noreferrer" className="social-icon-btn" title="WhatsApp">
            <img src="https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg" alt="WhatsApp" className="social-icon" />
          </a>
          <a href="https://www.tiktok.com" target="_blank" rel="noopener noreferrer" className="social-icon-btn" title="TikTok">
            <img src="https://upload.wikimedia.org/wikipedia/en/a/a9/TikTok_logo.svg" alt="TikTok" className="social-icon" />
          </a>
          <a href="https://www.instagram.com" target="_blank" rel="noopener noreferrer" className="social-icon-btn" title="Instagram">
            <img src="https://upload.wikimedia.org/wikipedia/commons/e/e7/Instagram_logo_2016.svg" alt="Instagram" className="social-icon" />
          </a>
        </div>
        <div>
          <p>© 2026 Shutter Stories Photography. All rights reserved.</p>
        </div>
      </footer>
    </div>
  );
}
